\begin{equation}
\label{biobjective_smooth}
    \min~F(x) = (f^a(x), f^b(x))^\top, \quad x \in \mathcal{X},
\end{equation}

where $\mathcal{X}$ is a nonempty bounded closed convex region. 
We say that the multi-objective problem is smooth if all objective functions~$f^i$ are continuously differentiable. In the convergence theory of our algorithms, we will assume that both functions are convex. Furthermore, both objectives involve randomness in its parameters, in which case we expect that a true gradient or subgradient is not available or too expensive to compute. Instead, one can access a unbiased estimator $g^i(x, \xi), i \in \{a, b\}$, of a true gradient or subgradient of $f^i$, where $\xi$ denotes some random variable.


The key idea of the alternating bi-objective optimization for solving~\eqref{biobjective_smooth} consists of iteratively taking $n_a$ gradient (or subgradient) descent steps for the first objective and then $n_b$ gradient (or subgradient) descent steps for the second objective. For simplicity, we denote such $n_a + n_b$ steps as one single iteration of the algorithm. The stochastic alternating bi-objective gradient or subgradient algorithm (SA2GD) is formally described in Algorithm~\ref{alg1_SA2GD}. At every iteration $t$, starting at $x_t = y^a_{0, t}$, the algorithm computes two sequences of intermediate iterates, $\{y^a_{r, t}\}_{r=1}^{n_a}$ and $\{y^b_{r, t}\}_{r=1}^{n_b}$. Let $P_{\mathcal{X}}$ denote the orthogonal projection operator that projects 
the new iterate back to the feasible region. Such an operator is well-defined because we assume a compact and convex feasible region.


\begin{algorithm}[ht]
\caption{Stochastic alternating bi-objective gradient (or subgradient) algorithm (SA2GD)} 
\label{alg1_SA2GD} 
\begin{algorithmic}[1]
\item \textbf{Input:} Initial point $x_0 = y^a_{0, 0}$ and a step size sequence $\{\alpha_t\}$.
\item \textbf{Output:} A likely non-dominated or Pareto solution $x_{T} = y^a_{0, T}$.
\item {\bf for} $t = 0, 1, \ldots, T-1$ {\bf do}
\item \quad {\bf for} $r = 0, \ldots, n_a-1$ {\bf do}
\item \quad \quad Generate a stochastic gradient $g^a(y^a_{r, t}, \xi^r_{t})$.
\item \quad \quad Update $y^a_{r+1, t} = y^a_{r, t} - \alpha_t g^a(y^a_{r, t}, \xi^r_{t})$. 
\item \quad Set $y^b_{0, t} = y^a_{n_a, t}$.
\item \quad {\bf for} $r = 0, \ldots, n_b - 1$ {\bf do}
\item \quad \quad Generate a stochastic gradient $g^b(y^b_{r, t}, \xi^{n_a + r}_{t})$.
\item \quad \quad Update $y^b_{r+1, t} = y^b_{r, t} - \alpha_t g^b(y^b_{r, t}, \xi^{n_a + r}_{t})$. 
\item \quad Set $x_{t+1} = y^a_{0, t+1} = P_{\mathcal{X}}(y^b_{n_b, t})$.
\par\vspace*{0.1cm}
\end{algorithmic}
\end{algorithm}

\begin{assumption}
\label{ass:limit_pts}
\textbf{(Bounded feasible region)}
The feasible region $\mathcal{X}$ is compact, and in particular there exists a positive constant $\Theta$ such that
\begin{equation*}
\displaystyle \max_{x, \bar{x} \in \mathcal{X}} \| x - \bar{x}\| \;\leq\; \textstyle \Theta \;<\; \infty.
\end{equation*}
\end{assumption}

\begin{assumption}
\label{ass:Lipschitz}
\textbf{(Lipschitz continuous gradients)} The individual true gradients are Lipschitz continuous with Lipschitz constants $L_i > 0, i \in \{a, b\}$, i.e., 
\begin{equation*}
    % \label{eq:Lipschitz}
    \begin{split}
        \|\nabla f^i(x) - \nabla f^i(\bar{x}) \| \;\leq\;& L_i \| x - \bar{x} \|, \quad \forall (x, \bar{x}) \in \mathcal{X} \times \mathcal{X}.
    \end{split}
\end{equation*}
\end{assumption}

Note that any continuous function  attains a maximum on a compact set, and thus one can assume the existence of positive constants~$M_\nabla^i$, $i \in \{a,b\}$, such that
\begin{equation} \label{Mnabla}
\| \nabla f^i(x) \|^2 \; \leq \; M_\nabla^i,  \quad \forall x \in \mathcal{X}.  
\end{equation}

\begin{assumption}
\label{ass:strongconv}
\textbf{(Strong convexity)} For all $i = \{a, b\}$, there exists a scalar $c_i > 0$ such that

\begin{equation*}
f^i(\bar{x}) \;\geq\; f^i(x) + \nabla f^i(x)^\top(\bar{x} - x) + \frac{c_i}{2} \| \bar{x} - x \|^2, \quad \forall (x,\bar{x}) \in \mathcal{X} \times \mathcal{X}.
\end{equation*}
\end{assumption}

Note that based on the above assumption, the weighted-sum function $S(x, \lambda) = \lambda f^a(x) + (1-\lambda)f^b(x), \lambda \in [0, 1]$, is also strongly convex with constant $c = \min(c_a, c_b)$. Given the individual stochastic gradients $g^i(x_t, \xi_t), \forall i \in \{a, b\}$, generated with random variable~$\xi_t$, we use $\mathbb{E}_{\xi_t}[\cdot]$ to denote the conditional expectation taken with respect to $\xi_t$. We also impose the following two classical assumptions of stochastic gradients. 


\begin{assumption}
\label{ass:gradient}
For both objective functions $i \in \{a, b\}$, and all iterates $t \in \mathbb{N}$, the individual stochastic gradients~$g^i(x_t, \xi_t)$ satisfy the following:
\begin{enumerate}
    \item[(a)]\textbf{(Unbiased gradient estimation)} 
    $\mathbb{E}_{\xi_t}[g^i(x_t, \xi_t)] \;=\; \nabla f^i(x_t), ~\forall i \in \{a, b\}$. 
    \item[(b)]\textbf{(Bound on the second moment)}
There exist positive scalars $G_i > 0$ and $\bar{G}_i > 0$ such that
\begin{equation*}
\begin{split}
\mathbb{E}_{\xi_t}[ g^i(x_t, \xi_t)\|^2] \;\leq\; G_i + \bar{G}_i\| \nabla f^i(x_t)\|^2, \quad \forall i \in \{a, b\}.
\end{split}
\end{equation*}
\end{enumerate}
\end{assumption}

