\begin{proof}
The proof is divided in three parts for better organization and understanding. In the first part, one obtains an upper bound on the norm of the iterates, $\mathbb{E}_{\xi_t}[\|x_{t+1} - x_*\|^2]$. Strong convexity of the weighted-sum function is applied in the second part. The third part concludes the proof using standard arguments. For simplicity, we let $z_t = y^b_{0, t} = y^a_{n_a, t}$ be the intermediate point at each iteration.  \vspace{1ex}

\noindent {\bf Part I: Bound on the iterates error using the Intermediate Value Theorem.} 
At any iteration $t$, the sequence of stochastic gradients is computed from drawing the sequence of random variables $\xi_t = \{\xi^0_t, \ldots, \xi^{n_a + n_b - 1}_t \}$. We have
\begin{align*}
    x_{t+1} - x_* & \;=\; P_{\mathcal{X}}\left(z_t - \alpha_t \sum_{r = 0}^{n_b - 1} g^b(y^b_{r, t}, \xi^r_t)\right) - x_*, \\
    &\;=\;P_{\mathcal{X}}\left(
    x_t - \alpha_t \sum_{r = 0}^{n_a - 1}  g^a(y^a_{r, t}, \xi^r_t) - \alpha_t \sum_{r = 0}^{n_b - 1}  g^b(y^b_{r, t}, \xi^{n_a + r}_t) \right) - x_*.
\end{align*}

Since the sequence $\xi_t$ is drawn independently, using Assumption~\ref{ass:gradient} (a) one has
\[\mathbb{E}_{\xi_t}[g^a(y_{r, t}^a, \xi_{t}^r)] \;=\; \mathbb{E}_{\xi_t^0, \ldots, \xi_{t}^{r-1}}[\mathbb{E}_{\xi_t^r}[g^a(y_{r, t}^a, \xi_{t}^r)]] \;=\; \mathbb{E}_{\xi_t^0, \ldots, \xi_{t}^{r-1}}[\nabla f^a(y_{r, t}^a)] \;=\; \mathbb{E}_{\xi_t}[\nabla f^a(y_{r, t}^a)],\]
where the last equality holds due to the independence between $y_{r, t}^a$ and $\{\xi_t^{r}, \ldots, \xi_t^{n_a + n_b - 1}\}$. Similarly, we have $\mathbb{E}_{\xi_t}[g^b(y_{r, t}^b, \xi_{t}^{n_a + r})] = \mathbb{E}_{\xi_t}[\nabla f^b(y_{r, t}^b)]$.
Then, taking square norms and expectations over the random variables $\xi_t$ on both sides yields
\begin{equation}
\label{theorem2_eq1}
    \begin{split}
    \mathbb{E}_{\xi_t}[\|x_{t+1} - x_*\|^2]  
     \;\leq\; & \|x_t - x_*\|^2 + \alpha_t^2\mathbb{E}_{\xi_t}[\|\sum_{r = 0}^{n_a - 1} g^a(y^a_{r, t}, \xi^r_t) + \sum_{r = 0}^{n_b - 1} g^b(y^b_{r, t}, \xi^{n_a + r}_t)\|^2] \\
     & - \mathbb{E}_{\xi_t}[2\alpha_t(x_t - x_*)^\top (\sum_{r = 0}^{n_a - 1} \nabla f^a(y^a_{r, t}) + \sum_{r = 0}^{n_b - 1} \nabla f^b(y^b_{r, t}))],
    \end{split}
\end{equation}
which holds by the non-expansiveness property of the orthogonal projection operator.

We now claim, by applying a version of the Intermediate Value Theorem given in Proposition~\ref{prop_ivt}, that the last term of the right-hand side in~\eqref{theorem2_eq1} can be written as $- 2\alpha_t(x_t - x_*)^\top \mathbb{E}_{\xi_t}[n_a \nabla f^a(w_t^a) + n_b \nabla f^b(w_t^b)]$ for some $w_t^a$ and $w_t^b$. In fact, we apply Proposition~\ref{prop_ivt} to the real continuous function $\phi^i(y) = -2\alpha_t(x_t - x_*)^\top \nabla f^i(y)$, from which we then know that $w_t^i$ is a convex linear combination of a sequence of points $\{y_{r, t}^i\}_{r = 0}^{n_i - 1}$ for both $i \in \{a, b\}$. 

Using a combination of~(\ref{Mnabla}) and Assumption~\ref{ass:gradient}~(b), the bound for the second moment of the stochastic gradients is given by
\begin{equation} \label{SGbound}
\mathbb{E}_{\xi_t}[\|g^i(y^i_{r, t}, \xi_t^r)\|^2] \; \leq \; G + \bar{G}M_{\nabla}, \quad
\mathbb{E}_{\xi_t}[\|g^i(y^i_{r, t}, \xi_t^r)\|] \; \leq \; \sqrt{G + \bar{G}M_{\nabla}},
\end{equation} 
where the second bound results from applying Jensen's inequality to the first one.
Hence, the second term in the right-hand side of~\eqref{theorem2_eq1} can be bounded by
\begin{equation*}
\begin{split}
   & \mathbb{E}_{\xi_t}[\|\sum_{r = 0}^{n_a - 1} g^a(y^a_{r, t}, \xi^r_t) + \sum_{r = 0}^{n_b - 1}  g^b(y^b_{r, t}, \xi^{n_a + r}_t)\|^2] \\
   &  \;\leq\; 2\mathbb{E}_{\xi_t}[\|\sum_{r = 0}^{n_a - 1}  g^a(y^a_{r, t}, \xi^r_t)\|^2] + 2\mathbb{E}_{\xi_t}[\|\sum_{r = 0}^{n_b - 1}  g^b(y^b_{r, t}, \xi^{n_a+r}_t)\|^2] \\
& \;\leq\;  2n_a\sum_{r = 0}^{n_a - 1} \mathbb{E}_{\xi_t}[\| g^a(y^a_{r, t}, \xi^r_t)\|^2] + 2n_b\sum_{r = 0}^{n_b - 1} \mathbb{E}_{\xi_t}[\| g^b(y^b_{r, t}, \xi^{n_a + r}_t)\|^2] \\
& \;\leq\;  2(n_a + n_b)^2(G + \bar{G}M_{\nabla}).
\end{split}
\end{equation*}
We thus arrive at
\begin{equation}
    \label{theorem2_eq2}
    \begin{split}
    \mathbb{E}_{\xi_t}[\|x_{t+1} - x_*\|^2]
    \;\leq\; &  \|x_t - x_*\|^2 + 2\alpha_t^2(n_a + n_b)^2(G + \bar{G}M_{\nabla}) \\
     & - 2\alpha_t(x_t - x_*)^\top \mathbb{E}_{\xi_t}[n_a \nabla f^a(w_t^a) + n_b \nabla f^b(w_t^b)].
    \end{split}
\end{equation}

By adding and subtracting $2\alpha_t(x_t - x_*)^\top(n_a\nabla f^a(x_t) + n_b \nabla f^b(x_t))$ in the right-hand side of~\eqref{theorem2_eq2}, we further rewrite it as
\begin{equation}
\label{theorem2_eq22}
    \begin{split}
    \mathbb{E}_{\xi_t}[\|x_{t+1} - x_*\|^2]
    \;\leq\; &  \|x_t - x_*\|^2 + 2\alpha_t^2(n_a + n_b)^2(G + \bar{G}M_{\nabla}) \\
     & - 2\alpha_t(x_t - x_*)^\top (n_a \nabla f^a(x_t) + n_b \nabla f^b(x_t)) \\
     & + 2\alpha_t\|x_t - x_*\|\mathbb{E}_{\xi_t}[\|n_a \nabla f^a(w_t^a) - n_a \nabla f^a(x_t)\|] \\
     & + 2\alpha_t\|x_t - x_*\|\mathbb{E}_{\xi_t}[\|n_b \nabla f^b(w^b_t) - n_b \nabla f^b(x_t)\|]. 
    \end{split}
\end{equation}
Note that the last two terms are derived by the Cauchy–Schwarz and Jensen's inequalities.

\vspace{2ex}
\noindent {\bf Part II: Using strong convexity.} 
Selecting $\lambda_* = \lambda(n_a, n_b) = n_a/(n_a + n_b)$, by the strong convexity of the weighted-sum function, one has
\begin{equation*}
 \nabla_x S(x_t, \lambda_*)^\top(x_t - x_*)  \;\geq\; S(x_t, \lambda_*) - S(x_*, \lambda_*) + \frac{c}{2}\| x_t - x_*\|^2,
\end{equation*}
which is equivalent to
\begin{equation}
\label{theorm2_eq3}
 (x_t - x_*)^\top(n_a \nabla f^a(x_t) + n_b \nabla f^b(x_t))  \;\geq\; (n_a + n_b)(S(x_t, \lambda_*) - S(x_*, \lambda_*) + \frac{c}{2}\| x_t - x_*\|^2).
\end{equation}

From Assumption~\ref{ass:Lipschitz}, we obtain a bound for the last two terms of~\eqref{theorem2_eq22} in the form 
\begin{equation}
    \label{theorem2_eq4}
    2\alpha_t\|x_t - x_*\|\mathbb{E}_{\xi_t}[\|n_i \nabla f^i(w_t^i) - n_i \nabla f^i(x_t)\|] \;\leq\;  2\alpha_tLn_i\|x_t - x_*\|\mathbb{E}_{\xi_t}[\|x_t - w_t^i\|], \forall i \in \{a, b\}.
\end{equation}
According to Proposition~\ref{prop_ivt}, $w_t^i$ is a convex linear combination of a sequence of points $\{y_{r, t}^i\}_{r = 0}^{n_i -1}$ for $i \in \{a, b\}$. One can write $w_t^i = \sum_{r=0}^{n_i - 1} \beta_r y_{r, t}^i$ with $\beta_r \geq 0$, $r = 0, \ldots, n_i - 1$ , and $\sum_{r=0}^{n_i - 1} \beta_r = 1$. An explicit upper bound of $\|x_t - w_t^i\|$ can then be derived as follows
\begin{equation}
\label{part2_eq2}
    \begin{split} 
        \|x_t - \sum_{r=0}^{n_i - 1} \beta_r y_{r, t}^i\| & \;=\; \|\sum_{r=0}^{n_i - 1} \beta_r (x_t - y_{r, t}^i)\| \;\leq\; \sum_{r=0}^{n_i - 1} \beta_r \|x_t - y_{r, t}^i\|.
    \end{split}
\end{equation}
Using $y_{r, t}^i = y_{0, t}^i - \sum_{j = 0}^{r-1}\alpha_t g^i(y_{j, t}^i, \xi_{t}^j)$ and applying the triangle inequality, we have
\begin{align}
    \|x_t - y_{r, t}^a\| \;\leq\; \alpha_t \sum_{j = 0}^{r-1} \|g^a(y^a_{j, t}, \xi_{t}^j)\|,\label{part2_eq3}
\end{align}  
and
\begin{equation}
\label{part2_eq4}
\begin{split}
    \|x_t - y_{r, t}^b\| & \;=\; \|x_t - y_{n_a, t}^a + \sum_{j = 0}^{r-1}\alpha_t g^b(y_{j, t}^b, \xi_{t}^{n_a + j})\| \\
    & \;\leq\; \alpha_t \sum_{j = 0}^{n_a-1} \|g^a(y^a_{j, t}, \xi_{t}^j)\| +  \alpha_t \sum_{j = 0}^{r-1} \|g^b(y^b_{j, t}, \xi_{t}^{n_a + j})\|.
\end{split}
\end{equation}
Plugging~\eqref{part2_eq3} into~\eqref{part2_eq2} with $i = a$ results in (note that $y^a_{0,t}=x_t$)
\begin{equation}\label{part2_eq5}
\begin{split}
       \|x_t - w_t^a\| & \;\leq\; \alpha_t \sum_{r=1}^{n_a - 1} \beta_r \sum_{j = 0}^{r-1} \|g^a(y^a_{j, t}, \xi_{t}^j)\| \\ & \;  = \;  \alpha_t 
       \sum_{j=0}^{n_a - 1} \|g^a(y^a_{j, t}, \xi_{t}^j)\|
      \sum_{r=j+1}^{n_a-1} \beta_r
       \;\leq \; \alpha_t  \sum_{j=0}^{n_a - 1} \|g^a(y^a_{j,t}, \xi_{t}^{j})\|.
\end{split}
\end{equation}


Applying expectations on both sides of~\eqref{part2_eq5}, followed by the bound~(\ref{SGbound}) on the second moment of the stochastic gradients,
\begin{equation} \label{part2_eq6}
\mathbb{E}_{\xi_t}[\|x_t - w_t^a\|] \; \leq \; \alpha_t n_a\sqrt{G + \bar{G}M_{\nabla}}.
\end{equation}
Similarly, merging~\eqref{part2_eq4} into~\eqref{part2_eq2} with $i = b$ leads to 
\begin{equation}
\label{part2_eq6.5}
        \|x_t - w_t^b\| \;\leq \; \alpha_t \sum_{j=0}^{n_a - 1} \|g^a(y^a_{j,t}, \xi_{t}^{j})\| + \alpha_t  \sum_{j=0}^{n_b - 1} \|g^b(y^b_{j,t}, \xi_{t}^{n_a+j})\|,
\end{equation}
and applying expectations
\begin{equation}
\label{part2_eq7}
        \mathbb{E}_{\xi_t}[\|x_t - w_t^b\|] \;\leq \; \alpha_t (n_a+n_b) \sqrt{G + \bar{G}M_{\nabla}}.
\end{equation}
Finally, combining~\eqref{theorem2_eq4}, \eqref{part2_eq6}, and~\eqref{part2_eq7} yields
\begin{equation}
\label{part2_eq8}
    \begin{split}
        2\alpha_t\|x_t - x_*\|\sum_{i \in \{a, b\}} \mathbb{E}_{\xi_t}[\|n_i \nabla f^i(w_t^i) - n_i \nabla f^i(x_t)\|] \;\leq\; 2\alpha_t^2L\Theta (n_a + n_b)^2\sqrt{G + \bar{G}M_{\nabla}}.
    \end{split}
\end{equation}

\vspace{2ex}
\noindent {\bf Part III: Bound on the optimality gap in terms of weighted-sum function.}
Applying inequalities \eqref{theorm2_eq3} and \eqref{part2_eq8} to \eqref{theorem2_eq22} leads to 
\begin{equation}
\label{smooth_sc_part3_eq1}
    \begin{split}
     \mathbb{E}_{\xi_t}[\|x_{t+1} - x_*\|^2]  \;\leq\; &  (1-\alpha_t(n_a + n_b)c) \|x_t - x_*\|^2 -  2\alpha_t(n_a + n_b)(S(x_t, \lambda_*) - S(x_*, \lambda_*)) \\
     & + \alpha^2_t M,
    \end{split}
\end{equation}
where we let $M = 2(n_a + n_b)^2 (G + \bar{G}M_{\nabla} +  L\Theta\sqrt{G + \bar{G}M_{\nabla}})$. Plugging in $\alpha_t = \frac{2}{c(n_a+n_b)(t+1)}$ and rearranging the last inequality result in 
\begin{equation*}
    \begin{split}
        S(x_t, \lambda_*) - S(x_*, \lambda_*)  \;\leq\; & \frac{(1-\alpha_t(n_a + n_b)c) \|x_t - x_*\|^2 - \mathbb{E}_{\xi_t}[\|x_{t+1} - x_*\|^2] + \alpha^2_t M}{2\alpha_t(n_a + n_b)} \\
        \;\leq\; & \frac{c(t-1)}{4}\|x_t - x_*\|^2  - \frac{c(t+1)}{4} \mathbb{E}_{\xi_t}[\|x_{t+1} - x_*\|^2] + \frac{\tilde{M}}{c(t+1)},
    \end{split}
\end{equation*}
where $\tilde{M} = \frac{M}{(n_a + n_b)^2}$. By taking total expectation over $\{\xi_t\}$, multiplying both sides by $t$, and summing over $t = 1, \ldots, T$, one obtains
\begin{equation*}
    \begin{split}
       \sum_{t=1}^T 
       t(\mathbb{E}[S(x_t, \lambda_*)] - S(x_*, \lambda_*)) \;\leq\; & \sum_{t=1}^T \left ( \frac{ct(t-1)}{4}\mathbb{E}[\|x_t - x_*\|^2]  - \frac{ct(t+1)}{4} \mathbb{E}[\|x_{t+1} - x_*\|^2]\right) \\
       & + \sum_{t=1}^T \frac{\tilde{M}t}{c(t+1)} \\
       \;\leq\; & -\frac{cT(T+1)}{4} \mathbb{E}[\|x_{T+1} - x_*\|^2] + \sum_{t=1}^T \frac{\tilde{M}t}{c(t+1)}  \;\leq\; \frac{T}{c} \tilde{M}. 
    \end{split}
\end{equation*}
Dividing both sides of the last inequality by $\sum_{t=1}^T t$ yields
\begin{equation*}
    \min_{t = 1, \ldots,T} \mathbb{E}[S(x_t, \lambda_*)] - S(x_*, \lambda_*) \;\leq\; \frac{2}{c(T + 1)} \tilde{M},   
\end{equation*}
which concludes the proof.
\end{proof}

